//! Playable geography: economic regions inside eight states of the Great Lakes and Ohio Valley.
//!
//! Generated by `tools/map/build_regions.py`. A region is the economic unit (labour, wages,
//! demand, land, markets, freight lanes); its state is the political layer (conditions, union
//! law, taxes) and every region in a state shares it. Populations are Census 2000 county
//! figures; incomes are SAIPE 2000; GDP, pay and union figures are rounded public circa-2000
//! values used only as relative indices; condition indices are authored game estimates.
//! Freight distances are anchor-to-anchor great-circle distances times a road factor.

use serde::{Deserialize, Serialize};

/// A playable state: the political layer over its regions.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct StateInfo {
    pub code: String,
    pub name: String,
    pub capital_hub: String,
    /// Census 2000 resident population (Great Lakes 2000).
    #[serde(default)]
    pub population_2000: i64,
    /// Census 1980 resident population (Texas Oil Patch 1981).
    #[serde(default)]
    pub population_1980: i64,
    /// July 1995 resident population estimate (Silicon Valley 1995).
    #[serde(default)]
    pub population_1995: i64,
    /// Primary then secondary specialized sector type.
    #[serde(default)]
    pub specialization: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Region {
    pub code: String,
    pub name: String,
    pub states: Vec<String>,
    pub principal_city: String,
    pub lat_milli: i32,
    pub lon_milli: i32,
    /// Engineering calibration: relative wage level, 10000 = corridor baseline.
    pub wage_index_bps: i32,
    /// Engineering calibration: relative weekly household demand volume.
    pub demand_index_bps: i32,
    /// Engineering calibration: relative land cost.
    pub land_index_bps: i32,
    /// Opening worker organisation, from rounded circa-2000 union membership.
    pub opening_organisation_bps: i32,
    /// Census 2000 resident population, for display (Great Lakes 2000).
    #[serde(default)]
    pub population_2000: i64,
    /// Census 1980 resident population, for display (Texas Oil Patch 1981).
    #[serde(default)]
    pub population_1980: i64,
    /// July 1995 resident population estimate, for display (Silicon Valley 1995).
    #[serde(default)]
    pub population_1995: i64,
    /// Authored condition indices that shape costs and productivity in the state.
    #[serde(default)]
    pub conditions: Conditions,
}

impl StateInfo {
    /// Resident population at the census of the scenario's start decade.
    pub fn population(&self) -> i64 {
        self.population_2000
            .max(self.population_1980)
            .max(self.population_1995)
    }
}

impl Region {
    /// Resident population at the census of the scenario's start decade.
    pub fn population(&self) -> i64 {
        self.population_2000
            .max(self.population_1980)
            .max(self.population_1995)
    }

    /// The state this region belongs to.
    pub fn state(&self) -> &str {
        self.states.first().map(String::as_str).unwrap_or("")
    }
}

/// State conditions, in basis points. Reliability, roads, broadband and skill: 10000 is best.
/// Crime and cost of living: 10000 is the corridor average.
#[derive(Clone, Copy, Debug, Serialize, Deserialize)]
pub struct Conditions {
    pub power_grid_bps: i32,
    pub road_bps: i32,
    pub broadband_bps: i32,
    pub skill_bps: i32,
    pub crime_bps: i32,
    pub cost_of_living_bps: i32,
}

impl Default for Conditions {
    fn default() -> Self {
        Conditions {
            power_grid_bps: 10_000,
            road_bps: 6_000,
            broadband_bps: 2_000,
            skill_bps: 5_000,
            crime_bps: 10_000,
            cost_of_living_bps: 10_000,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Lane {
    pub a: String,
    pub b: String,
    pub km: u32,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Geography {
    pub schema: u32,
    pub classification: String,
    pub vintage: String,
    pub official_source: String,
    pub attempts: Vec<String>,
    pub membership_status: String,
    pub notes: String,
    #[serde(default)]
    pub states: Vec<StateInfo>,
    pub regions: Vec<Region>,
    pub lanes: Vec<Lane>,
}

impl Geography {
    pub fn geometry_note(&self) -> String {
        format!(
            "{} | vintage: {} | {} | attempts: {}",
            self.classification,
            self.vintage,
            self.membership_status,
            self.attempts.join(" ; ")
        )
    }
}
